<?php namespace App\Http\Controllers; use App\Models\{MedicalDocument,Pet}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; class MedicalDocumentController extends Controller { public function index(Request $r,Pet $pet){abort_unless($pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);return $pet->medicalDocuments()->latest()->get();} public function store(Request $r){$data=$r->validate(['pet_id'=>'required|exists:pets,id','type'=>'required|string|max:100','title'=>'required|string|max:255','file'=>'required|file|mimes:pdf,jpg,jpeg,png|max:10240']);$pet=Pet::findOrFail($data['pet_id']);abort_unless($pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);$data['file_path']=$r->file('file')->store('medical-documents','private');unset($data['file']);return MedicalDocument::create($data);} public function download(Request $r,MedicalDocument $document){abort_unless($document->pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);return Storage::disk('local')->download($document->file_path,$document->title);} public function destroy(Request $r,MedicalDocument $document){abort_unless($document->pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);Storage::disk('local')->delete($document->file_path);$document->delete();return response()->noContent();} }